839	    }
840	    let mut go = |x: &Ex| walk_ex(x, f);
841	    match e {
842	        Ex::List(v) | Ex::Tuple(v) | Ex::Set(v) => v.iter().for_each(&mut go),
843	        Ex::Dict(items) => items.iter().for_each(|(k, v)| {
844	            if let Some(k) = k {
845	                go(k);
846	            }
847	            go(v);
848	        }),
849	        Ex::Star(x) | Ex::Unary(_, x) | Ex::Walrus(_, x) | Ex::YieldFrom(x) | Ex::Await(x) => go(x),
850	        Ex::Attr(x, _) => go(x),
851	        Ex::Index(a, b) | Ex::Bin(_, a, b) | Ex::And(a, b) | Ex::Or(a, b) => {
852	            go(a);
853	            go(b);
854	        }
855	        Ex::Slice(a, b, c) => [a, b, c].into_iter().flatten().for_each(|x| go(x)),
856	        Ex::Call(fx, args) => {
